import Foundation

let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\]\\s+(\\S+)\\s+\\(([^)]+)\\)\\s+-\\s+(.*)$"
guard let regex = try? NSRegularExpression(pattern: pattern) else {
    exit(1)
}

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    guard let match = regex.firstMatch(in: line, options: [], range: range) else { continue }

    let level = (line as NSString).substring(with: match.range(at: 3))
    let component = (line as NSString).substring(with: match.range(at: 4))
    let message = (line as NSString).substring(with: match.range(at: 5))
    let hourStr = (line as NSString).substring(with: match.range(at: 2))
    let hour = Int(hourStr) ?? 0

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }

    hourCounts[hour, default: 0] += 1
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")

let sortedComponents = errorComponentCounts.sorted {
    if $0.value != $1.value { return $0.value > $1.value }
    return $0.key < $1.key
}
if let top = sortedComponents.first {
    print("Component with Most Errors: \(top.key) (\(top.value) errors)")
}
print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")

let sortedHours = hourCounts.sorted {
    if $0.value != $1.value { return $0.value > $1.value }
    return $0.key < $1.key
}
if let top = sortedHours.first {
    print("Busiest Hour: \(String(format: "%02d", top.key)):00 (\(top.value) entries)")
}

