import * as fs from 'fs';

const filePath = '<tmp>';
const content = fs.readFileSync(filePath, 'utf-8');
const lines = content.split('\n').filter(l => l.trim().length > 0);

const regex = /^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

const levelCounts: Map<string, number> = new Map();
const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

for (const line of lines) {
    const m = line.match(regex);
    if (!m) continue;
    const hour = m[2];
    const level = m[3];
    const component = m[4];
    const message = m[5];

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

    if (level === 'ERROR') {
        errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
        errorMessages.add(message);
    }

    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
    out.push(`  ${level}: ${count}`);
}
out.push('');

let maxComp = '';
let maxCompCount = 0;
for (const [comp, count] of errorComponentCounts) {
    if (count > maxCompCount) {
        maxCompCount = count;
        maxComp = comp;
    }
}
out.push(`Component with Most Errors: ${maxComp} (${maxCompCount} errors)`);
out.push('');

out.push('Unique Error Messages:');
const sortedMsgs = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMsgs) {
    out.push(`  - ${msg}`);
}
out.push('');

let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
    if (count > busiestCount) {
        busiestCount = count;
        busiestHour = hour;
    }
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

