public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (InputStream is = conn.getInputStream()) {
            byte[] buf = new byte[4096];
            int n;
            while ((n = is.read(buf)) != -1) {
                baos.write(buf, 0, n);
            }
        }
        String json = baos.toString("UTF-8");

        List<String[]> products = parseProducts(json);

        List<String[]> filtered = products.stream()
                .filter(p -> Double.parseDouble(p[1]) > 50.00)
                .sorted(Comparator.comparing(p -> p[0]))
                .collect(Collectors.toList());

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        for (String[] p : filtered) {
            System.out.printf("%s: $%.2f%n", p[0], Double.parseDouble(p[1]));
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        double total = filtered.stream().mapToDouble(p -> Double.parseDouble(p[1])).sum();
        System.out.printf("Total: $%.2f%n", total);
    }

    static List<String[]> parseProducts(String json) {
        List<String[]> result = new ArrayList<>();
        String s = json.trim();
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);

        int i = 0;
        while (i < s.length()) {
            int start = s.indexOf('{', i);
            if (start == -1) break;
            int depth = 0;
            int end = start;
            while (end < s.length()) {
                char c = s.charAt(end);
                if (c == '"') {
                    end++;
                    while (end < s.length() && s.charAt(end) != '"') {
                        if (s.charAt(end) == '\\') end++;
                        end++;
                    }
                } else if (c == '{') {
                    depth++;
                } else if (c == '}') {
                    depth--;
                    if (depth == 0) break;
                }
                end++;
            }
            String obj = s.substring(start, end + 1);
            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");
            if (name != null && price != null) {
                result.add(new String[]{name, price});
            }
            i = end + 1;
        }
        return result;
    }

    static String extractString(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return null;
        idx += search.length();
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == ':')) idx++;
        if (idx >= obj.length() || obj.charAt(idx) != '"') return null;
        idx++;
        int start = idx;
        while (idx < obj.length() && obj.charAt(idx) != '"') {
            if (obj.charAt(idx) == '\\') idx++;
            idx++;
        }
        return obj.substring(start, idx);
    }

    static String extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return null;
        idx += search.length();
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == ':')) idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.'
                || obj.charAt(idx) == '-' || obj.charAt(idx) == '+'
                || obj.charAt(idx) == 'e' || obj.charAt(idx) == 'E')) {
            idx++;
        }
        String num = obj.substring(start, idx);
        return num.isEmpty() ? null : num;
    }
}

