    FILE *f = fopen(CSV_PATH, "r");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", CSV_PATH);
        return 1;
    }

    Employee *emps = NULL;
    int n_emps = 0, cap_emps = 0;

    Dept *depts = NULL;
    int n_depts = 0, cap_depts = 0;

    double total_budget = 0.0;
    double max_salary = -1.0;
    char *max_name = NULL;

    char *line = malloc(8192);
    if (!line) return 1;

    int first_line = 1;

    while (fgets(line, 8192, f)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[len - 1] = '\0';
            len--;
        }
        if (len == 0) continue;

        if (first_line) {
            first_line = 0;
            continue;
        }

        char *fields[6];
        int nfields = 0;
        char *p = line;
        fields[nfields++] = p;
        while (*p) {
            if (*p == ',') {
                *p = '\0';
                fields[nfields++] = p + 1;
            }
            p++;
        }

        if (nfields < 6) continue;

        char *name = fields[1];
        char *dept_name = fields[2];
        double salary = atof(fields[3]);

        if (n_emps >= cap_emps) {
            cap_emps = cap_emps ? cap_emps * 2 : 64;
            emps = realloc(emps, cap_emps * sizeof(Employee));
        }
        emps[n_emps].name = strdup(name);
        emps[n_emps].department = strdup(dept_name);
        emps[n_emps].salary = salary;
        n_emps++;

        total_budget += salary;

        if (salary > max_salary) {
            max_salary = salary;
            free(max_name);
            max_name = strdup(name);
        }

        int found = -1;
        for (int i = 0; i < n_depts; i++) {
            if (strcmp(depts[i].name, dept_name) == 0) {
                found = i;
                break;
            }
        }
        if (found == -1) {
            if (n_depts >= cap_depts) {
                cap_depts = cap_depts ? cap_depts * 2 : 16;
                depts = realloc(depts, cap_depts * sizeof(Dept));
            }
            depts[n_depts].name = strdup(dept_name);
            depts[n_depts].sum = salary;
            depts[n_depts].count = 1;
            n_depts++;
        } else {
            depts[found].sum += salary;
            depts[found].count++;
        }
    }

    fclose(f);
    free(line);

    qsort(depts, n_depts, sizeof(Dept), dept_cmp);

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < n_depts; i++) {
        char buf[128];
        double avg = depts[i].sum / depts[i].count;
        format_number(avg, 2, buf, sizeof(buf));
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    printf("Highest Paid: %s ($", max_name ? max_name : "");
    {
        char buf[128];
        format_number(max_salary, 0, buf, sizeof(buf));
        printf("%s)\n", buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < n_depts; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    printf("Total Budget: $");
    {
        char buf[128];
        format_number(total_budget, 0, buf, sizeof(buf));
        printf("%s\n", buf);
    }

    for (int i = 0; i < n_emps; i++) {
        free(emps[i].name);
        free(emps[i].department);
    }
    free(emps);
    for (int i = 0; i < n_depts; i++) {
        free(depts[i].name);
    }
    free(depts);
    free(max_name);

    return 0;
}
