        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::Str(self.parse_string()),
            Some('t') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\x08'),
                    Some('f') => s.push('\x0c'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            if let Some(c) = self.next() {
                                code = code * 16 + c.to_digit(16).unwrap_or(0);
                            }
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => {}
                },
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        self.skip_ws();
        let start = self.pos;
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.data[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap_or(0.0))
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.pos += 1;
            return Json::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            if self.expect(',') {
                continue;
            }
            self.expect(']');
            break;
        }
        Json::Array(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.pos += 1;
            return Json::Object(obj);
        }
        loop {
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            if self.expect(',') {
                continue;
            }
            self.expect('}');
            break;
        }
        Json::Object(obj)
    }
}

fn get_field<'a>(obj: &'a Vec<(String, Json)>, key: &str) -> Option<&'a Json> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");

    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write");
    stream.flush().expect("Failed to flush");

    let mut response = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => response.extend_from_slice(&buf[..n]),
            Err(_) => break,
        }
    }

    let response_str = String::from_utf8_lossy(&response).to_string();

    let body = if let Some(idx) = response_str.find("\r\n\r\n") {
        &response_str[idx + 4..]
    } else if let Some(idx) = response_str.find("\n\n") {
        &response_str[idx + 2..]
    } else {
        &response_str
    };

    let mut parser = Parser::new(body);
    let json = parser.parse_value();

    let mut products: Vec<(String, f64)> = Vec::new();

    if let Json::Array(arr) = json {
        for item in arr {
            if let Json::Object(fields) = item {
                let name = match get_field(&fields, "name") {
                    Some(Json::Str(s)) => s.clone(),
                    _ => String::new(),
                };
                let price = match get_field(&fields, "price") {
                    Some(Json::Number(n)) => *n,
                    _ => 0.0,
                };
                products.push((name, price));
            }
        }
    }

    products.retain(|(_, price)| *price > 50.00);

    products.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &products {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", products.len());
    let total: f64 = products.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}
