        }

        Map<String, Object> parseObj() {
            i++; // {
            Map<String, Object> m = new LinkedHashMap<>();
            skipWs();
            if (s.charAt(i) == '}') { i++; return m; }
            while (true) {
                skipWs();
                String k = parseStr();
                skipWs();
                i++; // :
                Object v = parse();
                m.put(k, v);
                skipWs();
                if (s.charAt(i) == ',') { i++; }
                else { i++; break; } // }
            }
            return m;
        }

        List<Object> parseArr() {
            i++; // [
            List<Object> l = new ArrayList<>();
            skipWs();
            if (s.charAt(i) == ']') { i++; return l; }
            while (true) {
                Object v = parse();
                l.add(v);
                skipWs();
                if (s.charAt(i) == ',') { i++; }
                else { i++; break; } // ]
            }
            return l;
        }

        String parseStr() {
            i++; // opening quote
            StringBuilder sb = new StringBuilder();
            while (s.charAt(i) != '"') {
                char c = s.charAt(i);
                if (c == '\\') {
                    i++;
                    char e = s.charAt(i);
                    if (e == 'n') sb.append('\n');
                    else if (e == 't') sb.append('\t');
                    else if (e == 'r') sb.append('\r');
                    else if (e == 'b') sb.append('\b');
                    else if (e == 'f') sb.append('\f');
                    else sb.append(e);
                } else {
                    sb.append(c);
                }
                i++;
            }
            i++; // closing quote
            return sb.toString();
        }

        Object parseNum() {
            int start = i;
            while (i < s.length()) {
                char c = s.charAt(i);
                if (Character.isDigit(c) || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E') i++;
                else break;
            }
            String t = s.substring(start, i);
            if (t.contains(".") || t.contains("e") || t.contains("E")) return (Object) Double.parseDouble(t);
            return (Object) Long.parseLong(t);
        }
    }

    static class Entry implements Comparable<Entry> {
        long d;
        String node;
        Entry(long d, String node) { this.d = d; this.node = node; }
