            if (adj.containsKey(from)) adj.get(from).add(new long[]{w});
            if (adj.containsKey(to)) adj.get(to).add(new long[]{w});
            // store neighbor via parallel structure: rebuild below
        }

        // Rebuild adjacency with neighbor names (simpler: parse again into proper structure)
        adj.clear();
        for (String n : nodes) adj.put(n, new ArrayList<>());
        Map<String, List<String>> adjNames = new HashMap<>();
        for (String n : nodes) adjNames.put(n, new ArrayList<>());
        for (Object e : (List<?>) root.get("edges")) {
            Map<String, Object> eo = (Map<String, Object>) e;
            String from = (String) eo.get("from");
            String to = (String) eo.get("to");
            long w = ((Number) eo.get("weight")).longValue();
            if (adj.containsKey(from)) { adj.get(from).add(new long[]{w}); adjNames.get(from).add(to); }
            if (adj.containsKey(to)) { adj.get(to).add(new long[]{w}); adjNames.get(to).add(from); }
        }

        // Dijkstra
        final long INF = Long.MAX_VALUE / 4;
        Map<String, Long> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, INF);
        dist.put("A", 0L);

        PriorityQueue<Entry> pq = new PriorityQueue<>();
        pq.add(new Entry(0L, "A"));

        while (!pq.isEmpty()) {
            Entry cur = pq.poll();
            if (cur.d > dist.get(cur.node)) continue;
            List<long[]> ws = adj.get(cur.node);
            List<String> ns = adjNames.get(cur.node);
            if (ws == null) continue;
            for (int k = 0; k < ws.size(); k++) {
                String nb = ns.get(k);
                long nd = cur.d + ws.get(k)[0];
                if (nd < dist.get(nb)) {
                    dist.put(nb, nd);
                    pq.add(new Entry(nd, nb));
                }
            }
        }

        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sorted) {
            long d = dist.get(n);
            if (d >= INF) {
                System.out.println("A -> " + n + ": unreachable");
            } else {
                System.out.println("A -> " + n + ": " + d);
            }
        }
    }
}

