use std::collections::HashMap;
use std::fs;

fn format_int_comma(n: i64) -> String {
    let negative = n < 0;
    let abs = if negative { -n } else { n };
    let s = abs.to_string();
    let bytes = s.as_bytes();
    let mut result = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    if negative {
        result.insert(0, '-');
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut employees: Vec<(String, String, f64)> = Vec::new();

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().unwrap_or(0.0);
        employees.push((name, department, salary));
    }

    let mut dept_sum: HashMap<String, f64> = HashMap::new();
    let mut dept_count: HashMap<String, usize> = HashMap::new();

    for (_name, dept, salary) in &employees {
        *dept_sum.entry(dept.clone()).or_insert(0.0) += salary;
        *dept_count.entry(dept.clone()).or_insert(0) += 1;
    }

    let mut depts: Vec<&String> = dept_count.keys().collect();
    depts.sort();

    let highest = employees.iter().max_by(|a, b| a.2.partial_cmp(&b.2).unwrap());

    let total: f64 = employees.iter().map(|e| e.2).sum();

    let mut big_depts: Vec<&String> = depts.iter().filter(|d| dept_count.get(*d).unwrap() > 2).collect();
    big_depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let avg = dept_sum[dept] / dept_count[dept] as f64;
        let int_part = avg as i64;
        let dec_part = ((avg - int_part as f64) * 100.0).round() as i32;
        let int_str = format_int_comma(int_part);
        println!("  {}: ${}.{:02}", dept, int_str, dec_part);
    }
    println!();
    if let Some((name, _, salary)) = highest {
        let int_salary = *salary as i64;
        println!("Highest Paid: {} (${})", name, format_int_comma(int_salary));
    }
    println!();
    println!("Departments with >2 employees:");
    for dept in &big_depts {
        println!("  {} ({} employees)", dept, dept_count[dept]);
    }
    println!();
    let total_int = total as i64;
    println!("Total Budget: ${}", format_int_comma(total_int));
}

