    let abs = if negative { -n } else { n };
    let s = abs.to_string();
    let bytes = s.as_bytes();
    let mut result = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    if negative {
        result.insert(0, '-');
    }
    result
}

