        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().unwrap_or(0.0);
        employees.push((name, department, salary));
    }

    let mut dept_sum: HashMap<String, f64> = HashMap::new();
    let mut dept_count: HashMap<String, usize> = HashMap::new();

    for (_name, dept, salary) in &employees {
        *dept_sum.entry(dept.clone()).or_insert(0.0) += salary;
        *dept_count.entry(dept.clone()).or_insert(0) += 1;
