use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

fn json_eq(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Null, Json::Null) => true,
        (Json::Bool(x), Json::Bool(y)) => x == y,
        (Json::Number(x), Json::Number(y)) => x == y,
        (Json::String(x), Json::String(y)) => x == y,
        (Json::Array(x), Json::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| json_eq(a, b))
        }
        (Json::Object(x), Json::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map_or(false, |v2| json_eq(v, v2)))
        }
        _ => false,
    }
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::String),
            Some(b't') => self.parse_literal("true", Json::Bool(true)),
            Some(b'f') => self.parse_literal("false", Json::Bool(false)),
            Some(b'n') => self.parse_literal("null", Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("Unexpected character at position {}", self.pos)),
        }
    }

    fn parse_literal(&mut self, lit: &str, val: Json) -> Result<Json, String> {
        let lb = lit.as_bytes();
        if self.input.len() - self.pos >= lb.len()
            && &self.input[self.pos..self.pos + lb.len()] == lb
        {
            self.pos += lb.len();
            Ok(val)
        } else {
            Err(format!("Invalid literal at position {}", self.pos))
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1; // consume opening "
        let mut result = String::new();
        loop {
            if self.pos >= self.input.len() {
                return Err("Unterminated string".into());
            }
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                return Ok(result);
            } else if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() {
                    return Err("Unterminated escape".into());
                }
                let esc = self.input[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        if self.pos + 4 > self.input.len() {
                            return Err("Invalid \\u escape".into());
                        }
                        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4])
                            .map_err(|_| "Invalid \\u escape".to_string())?;
                        let code = u32::from_str_radix(hex, 16)
                            .map_err(|_| "Invalid \\u escape".to_string())?;
                        self.pos += 4;
                        if (0xD800..=0xDBFF).contains(&code) {
                            if self.pos + 6 <= self.input.len()
                                && self.input[self.pos] == b'\\'
                                && self.input[self.pos + 1] == b'u'
                            {
                                let hex2 = std::str::from_utf8(
                                    &self.input[self.pos + 2..self.pos + 6],
                                )
                                .map_err(|_| "Invalid \\u escape".to_string())?;
                                let code2 = u32::from_str_radix(hex2, 16)
                                    .map_err(|_| "Invalid \\u escape".to_string())?;
                                if (0xDC00..=0xDFFF).contains(&code2) {
                                    self.pos += 6;
                                    let combined =
                                        0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00);
                                    result.push(char::from_u32(combined).unwrap_or('\u{FFFD}'));
                                } else {
                                    result.push('\u{FFFD}');
                                    self.pos += 6;
                                }
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else {
                            result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => return Err(format!("Invalid escape at position {}", self.pos)),
                }
            } else {
                let byte = c;
                let len = if byte < 0x80 {
                    1
                } else if byte & 0xE0 == 0xC0 {
                    2
                } else if byte & 0xF0 == 0xE0 {
                    3
                } else if byte & 0xF8 == 0xF0 {
                    4
                } else {
                    1
                };
                if self.pos + len > self.input.len() {
                    return Err("Invalid UTF-8 in string".into());
                }
                let s = std::str::from_utf8(&self.input[self.pos..self.pos + len])
                    .map_err(|_| "Invalid UTF-8 in string".to_string())?;
                result.push_str(s);
                self.pos += len;
            }
        }
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.pos += 1;
        }
        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
            }
        } else {
            return Err("Invalid number".into());
        }
