            out[o++] = '\\'; out[o++] = 'n';
        } else if (c == '\r') {
            out[o++] = '\\'; out[o++] = 'r';
        } else if (c == '\t') {
            out[o++] = '\\'; out[o++] = 't';
        } else if (c < 0x20) {
            o += (size_t)snprintf(out + o, outcap - o, "\\u%04x", c);
        } else {
            out[o++] = (char)c;
        }
    }
    out[o] = '\0';
}

static char *run_command(const char *cmd) {
    size_t cap = 4096;
    size_t total = 0;
    char *buffer = malloc(cap);
    if (!buffer) return NULL;

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        free(buffer);
        return NULL;
    }

    for (;;) {
        if (total >= cap) {
            cap *= 2;
            char *tmp = realloc(buffer, cap);
            if (!tmp) {
                free(buffer);
                pclose(fp);
                return NULL;
            }
            buffer = tmp;
        }
        size_t n = fread(buffer + total, 1, cap - total, fp);
        total += n;
        if (n == 0) break;
    }
    pclose(fp);

    /* strip trailing whitespace / newlines */
    while (total > 0) {
        char c = buffer[total - 1];
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t') {
            buffer[--total] = '\0';
        } else {
            break;
        }
    }
    if (total == 0) buffer[0] = '\0';

    return buffer;
}

