import * as fs from 'fs';
import * as path from 'path';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function walkDir(dir: string, root: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      continue;
    }

    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      results.push(...walkDir(fullPath, root, visited));
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      let content: Buffer;
      try {
        content = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const chars = content.length;
      let lines: number;
      if (chars === 0) {
        lines = 0;
      } else {
        const str = content.toString('utf-8');
        const parts = str.split('\n');
        if (parts[parts.length - 1] === '') {
          parts.pop();
        }
        lines = parts.length;
      }
      results.push({ relativePath, lines, chars });
    }
  }

  return results;
}

function main(): void {
  const rootDir = '<tmp>';

  let realRoot: string;
  try {
    realRoot = fs.realpathSync(rootDir);
  } catch {
    realRoot = rootDir;
  }

  const visited = new Set<string>();
  visited.add(realRoot);

  const files = walkDir(rootDir, rootDir, visited);

  const groups = new Map<string, FileInfo[]>();
  for (const f of files) {
    const ext = path.extname(f.relativePath);
    if (!groups.has(ext)) {
      groups.set(ext, []);
    }
    groups.get(ext)!.push(f);
  }

  const sortedExts = Array.from(groups.keys()).sort();

  for (const ext of sortedExts) {
    groups.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
  }

  let out = '';
  out += '=== File Tree Analysis ===\n';
  out += '\n';

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  for (const ext of sortedExts) {
    const group = groups.get(ext)!;
    const gLines = group.reduce((s, f) => s + f.lines, 0);
    const gChars = group.reduce((s, f) => s + f.chars, 0);

    out += `Extension: ${ext}\n`;
    out += `  Files: ${group.length}\n`;
    out += `  Total Lines: ${gLines}\n`;
    out += `  Total Characters: ${gChars}\n`;
    for (const f of group) {
      out += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
    }

    totalFiles += group.length;
    totalLines += gLines;
    totalChars += gChars;
  }

  out += '\n';
  out += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

  process.stdout.write(out);
}

main();

