public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileInfo>> extMap = new TreeMap<>();

        try (Stream<Path> walk = Files.walk(root)) {
            walk.filter(p -> !Files.isSymbolicLink(p))
                .filter(p -> Files.isRegularFile(p))
                .forEach(p -> {
                    try {
                        String ext = getExtension(p.getFileName().toString());
                        long bytes = Files.size(p);
                        long lines = countLines(p);
                        String relPath = root.relativize(p).toString().replace('\\', '/');
                        extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                              .add(new FileInfo(relPath, lines, bytes));
                    } catch (IOException e) {
                        // skip unreadable files
                    }
                });
        }

        for (List<FileInfo> list : extMap.values()) {
            list.sort(Comparator.comparing(f -> f.relPath));
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();

            long extLines = files.stream().mapToLong(f -> f.lines).sum();
            long extChars = files.stream().mapToLong(f -> f.chars).sum();

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files.size());
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);

            for (FileInfo f : files) {
                System.out.println("    " + f.relPath + ": " + f.lines + " lines, " + f.chars + " chars");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static String getExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot <= 0) {
            return "(no extension)";
        }
        return filename.substring(lastDot);
    }

    static long countLines(Path path) throws IOException {
        byte[] data = Files.readAllBytes(path);
        if (data.length == 0) return 0;
        long newlines = 0;
        for (byte b : data) {
            if (b == '\n') newlines++;
        }
        if (data[data.length - 1] != '\n') newlines++;
        return newlines;
    }

    static class FileInfo {
        String relPath;
        long lines;
        long chars;

        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }
}

