        p++;
    return p;
}

static char *parse_json_string(char *p, char *out, int out_size) {
    p = skip_ws(p);
    if (*p != '"') return NULL;
    p++;
    int i = 0;
    while (*p && *p != '"') {
        if (*p == '\\') {
            p++;
            if (i + 1 < out_size) out[i++] = *p;
        } else {
            if (i + 1 < out_size) out[i++] = *p;
        }
        p++;
    }
    out[i] = '\0';
    if (*p == '"') p++;
    else return NULL;
    return p;
}

static char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = (char *)malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

static int find_node(char **names, int count, const char *name) {
