    int r = strcmp(ea->ext, eb->ext);
    if (r != 0) return r;
    return strcmp(ea->rel_path, eb->rel_path);
}

static char *get_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (dot) {
        return strdup(dot);
    }
    return strdup("");
}

static void count_file(const char *full_path, long *lines, long *chars) {
    FILE *f = fopen(full_path, "rb");
    if (!f) {
        *lines = 0;
        *chars = 0;
        return;
    }
    long line_count = 0;
    long char_count = 0;
    int last_char = 0;
    int has_content = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        char_count++;
        last_char = c;
        has_content = 1;
        if (c == '\n') line_count++;
    }
    if (has_content && last_char != '\n') {
        line_count++;
    }
    *lines = line_count;
    *chars = char_count;
    fclose(f);
}

static void walk_dir(const char *dir_path, const char *rel_prefix,
                     FileEntry ***entries, int *count, int *capacity) {
    DIR *d = opendir(dir_path);
    if (!d) return;
    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char full_path[PATH_MAX];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);
        struct stat st;
        if (lstat(full_path, &st) != 0)
            continue;
        if (S_ISLNK(st.st_mode))
            continue;
        if (S_ISDIR(st.st_mode)) {
            char rel_sub[PATH_MAX];
            if (rel_prefix[0])
                snprintf(rel_sub, sizeof(rel_sub), "%s/%s", rel_prefix, entry->d_name);
            else
                snprintf(rel_sub, sizeof(rel_sub), "%s", entry->d_name);
            walk_dir(full_path, rel_sub, entries, count, capacity);
        } else if (S_ISREG(st.st_mode)) {
            char rel_path[PATH_MAX];
            if (rel_prefix[0])
                snprintf(rel_path, sizeof(rel_path), "%s/%s", rel_prefix, entry->d_name);
            else
                snprintf(rel_path, sizeof(rel_path), "%s", entry->d_name);
            long lines, chars;
            count_file(full_path, &lines, &chars);
            if (*count >= *capacity) {
                *capacity = *capacity ? *capacity * 2 : 64;
                *entries = realloc(*entries, (size_t)*capacity * sizeof(FileEntry *));
                if (!*entries) {
                    fprintf(stderr, "out of memory\n");
                    exit(1);
                }
            }
            FileEntry *fe = malloc(sizeof(FileEntry));
            if (!fe) {
                fprintf(stderr, "out of memory\n");
                exit(1);
            }
            fe->rel_path = strdup(rel_path);
            fe->ext = get_extension(entry->d_name);
            fe->lines = lines;
            fe->chars = chars;
            (*entries)[*count] = fe;
            (*count)++;
        }
    }
    closedir(d);
}

int main(void) {
    FileEntry **entries = NULL;
    int count = 0, capacity = 0;

    walk_dir(BASE_DIR, "", &entries, &count, &capacity);

    if (count > 0) {
        qsort(entries, (size_t)count, sizeof(FileEntry *), combined_cmp);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0;
    long total_lines = 0;
    long total_chars = 0;

    int i = 0;
    while (i < count) {
        const char *cur_ext = entries[i]->ext;
        int j = i;
        long group_files = 0;
        long group_lines = 0;
        long group_chars = 0;
        while (j < count && strcmp(entries[j]->ext, cur_ext) == 0) {
            group_files++;
            group_lines += entries[j]->lines;
            group_chars += entries[j]->chars;
            j++;
        }
        printf("Extension: %s\n", cur_ext);
        printf("  Files: %ld\n", group_files);
        printf("  Total Lines: %ld\n", group_lines);
        printf("  Total Characters: %ld\n", group_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n",
                   entries[k]->rel_path, entries[k]->lines, entries[k]->chars);
        }
        total_files += group_files;
        total_lines += group_lines;
        total_chars += group_chars;
        i = j;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n",
           total_files, total_lines, total_chars);

    for (int k = 0; k < count; k++) {
        free(entries[k]->rel_path);
        free(entries[k]->ext);
        free(entries[k]);
    }
    free(entries);

    return 0;
}
