public class Main {
    public static void main(String[] args) throws Exception {
        String os = runCommand("uname -s");
        String architecture = runCommand("uname -m");
        String username = runCommand("whoami");
        String hostname = runCommand("hostname");

        System.out.println("{");
        System.out.println("  \"hostname\": \"" + jsonEscape(hostname) + "\",");
        System.out.println("  \"os\": \"" + jsonEscape(os) + "\",");
        System.out.println("  \"architecture\": \"" + jsonEscape(architecture) + "\",");
        System.out.println("  \"username\": \"" + jsonEscape(username) + "\"");
        System.out.println("}");
    }

    private static String runCommand(String cmd) throws Exception {
        String[] parts = cmd.split("\\s+");
        ProcessBuilder pb = new ProcessBuilder(parts);
        pb.redirectErrorStream(true);
        Process process = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            if (sb.length() > 0) {
                sb.append("\n");
            }
            sb.append(line);
        }
        process.waitFor();
        reader.close();
        return sb.toString().trim();
    }

    private static String jsonEscape(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '"':  sb.append("\\\""); break;
                case '\b': sb.append("\\b");  break;
                case '\f': sb.append("\\f");  break;
                case '\n': sb.append("\\n");  break;
                case '\r': sb.append("\\r");  break;
                case '\t': sb.append("\\t");  break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
                    break;
            }
        }
        return sb.toString();
    }
}

