                for (int k = 0; k < n; k++) {
                    if (k < j) minor[i - 1][k] = M[i][k];
                    else if (k > j) minor[i - 1][k - 1] = M[i][k];
                }
            det += (j % 2 == 0 ? 1 : -1) * M[0][j] * determinant(minor);
        }
        return det;
