use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::io::Read;
use std::path::Path;

fn walk(
    dir: &Path,
    root: &Path,
    groups: &mut BTreeMap<String, Vec<(String, u64, u64)>>,
    total_files: &mut u64,
    total_lines: &mut u64,
    total_chars: &mut u64,
    visited: &mut HashSet<u64>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            let meta = match fs::metadata(&path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            let ino = meta.ino();
            if visited.contains(&ino) {
                continue;
            }
            visited.insert(ino);
            walk(&path, root, groups, total_files, total_lines, total_chars, visited);
        } else if path.is_file() {
            let mut file = match fs::File::open(&path) {
                Ok(f) => f,
                Err(_) => continue,
            };

            let mut buf: Vec<u8> = Vec::new();
            if file.read_to_end(&mut buf).is_err() {
                continue;
            }

            let char_count = buf.len() as u64;

            let line_count = if buf.is_empty() {
                0
            } else {
                let nl_count = buf.iter().filter(|&&b| b == b'\n').count() as u64;
                if buf.last() == Some(&b'\n') {
                    nl_count
                } else {
                    nl_count + 1
                }
            };

            let rel = path.strip_prefix(root).unwrap();
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            let ext = path
                .extension()
                .map(|e| format!(".{}", e))
                .unwrap_or_else(|| String::new());

            groups.entry(ext).or_default().push((rel_str, line_count, char_count));

            *total_files += 1;
            *total_lines += line_count;
            *total_chars += char_count;
        }
    }
}

fn main() {
    let root = Path::new(
        "<tmp>",
    );

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;
    let mut visited: HashSet<u64> = HashSet::new();

    if let Ok(meta) = fs::metadata(root) {
        visited.insert(meta.ino());
    }

    walk(
        root,
        root,
        &mut groups,
        &mut total_files,
        &mut total_lines,
        &mut total_chars,
        &mut visited,
    );

    for files in groups.values_mut() {
        files.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, files) in &groups {
        println!("Extension: {}", ext);
        println!("  Files: {}", files.len());
        let tl: u64 = files.iter().map(|f| f.1).sum();
        let tc: u64 = files.iter().map(|f| f.2).sum();
        println!("  Total Lines: {}", tl);
        println!("  Total Characters: {}", tc);
        for (rel, lines, chars) in files {
            println!("    {}: {} lines, {} chars", rel, lines, chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

