use std::fs;
use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self { Some(s) } else { None }
    }
    fn as_num(&self) -> Option<f64> {
        if let Json::Num(n) = self { Some(*n) } else { None }
    }
    fn as_arr(&self) -> Option<&Vec<Json>> {
        if let Json::Arr(a) = self { Some(a) } else { None }
    }
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { data: s.as_bytes(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() && (self.data[self.pos] as char).is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn expect(&mut self, c: u8) -> Result<(), String> {
        self.skip_whitespace();
        if self.peek() == Some(c) {
            self.pos += 1;
            Ok(())
        } else {
            Err(format!("Expected '{}' at pos {}", c as char, self.pos))
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Json::Str(self.parse_string()?)),
            Some(b't') => { self.parse_literal("true")?; Ok(Json::Bool(true)) }
            Some(b'f') => { self.parse_literal("false")?; Ok(Json::Bool(false)) }
            Some(b'n') => { self.parse_literal("null")?; Ok(Json::Null) }
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("Unexpected char at pos {}", self.pos)),
        }
    }

    fn parse_literal(&mut self, lit: &str) -> Result<(), String> {
        let lb = lit.as_bytes();
        if self.data.len() - self.pos >= lb.len()
            && &self.data[self.pos..self.pos + lb.len()] == lb
        {
            self.pos += lb.len();
            Ok(())
        } else {
            Err(format!("Expected '{}' at pos {}", lit, self.pos))
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut s = String::new();
        loop {
            let c = self.data.get(self.pos).copied().ok_or("EOF in string")?;
            self.pos += 1;
            if c == b'"' {
                break;
            } else if c == b'\\' {
                let esc = self.data.get(self.pos).copied().ok_or("EOF in escape")?;
                self.pos += 1;
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'n' => s.push('\n'),
                    b't' => s.push('\t'),
                    b'r' => s.push('\r'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0C'),
                    b'u' => {
                        if self.pos + 4 > self.data.len() {
                            return Err("bad unicode escape".into());
                        }
                        let hex = std::str::from_utf8(&self.data[self.pos..self.pos + 4])
                            .map_err(|_| "bad unicode escape")?;
                        let cp = u32::from_str_radix(hex, 16).map_err(|_| "bad hex")?;
                        self.pos += 4;
                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    }
                    _ => return Err("bad escape".into()),
                }
            } else {
                s.push(c as char);
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.peek() == Some(b'.') {
            self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap();
        s.parse::<f64>().map(Json::Num).map_err(|e| e.to_string())
    }

    fn parse_array(&mut self) -> Result<Json, String> {
        self.expect(b'[')?;
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Ok(Json::Arr(arr));
        }
        loop {
            arr.push(self.parse_value()?);
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err(format!("Expected ',' or ']' at pos {}", self.pos)),
            }
        }
        Ok(Json::Arr(arr))
    }

    fn parse_object(&mut self) -> Result<Json, String> {
        self.expect(b'{')?;
        let mut pairs = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(Json::Obj(pairs));
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string()?;
            self.expect(b':')?;
            let val = self.parse_value()?;
            pairs.push((key, val));
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err(format!("Expected ',' or '}}' at pos {}", self.pos)),
            }
        }
        Ok(Json::Obj(pairs))
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value().expect("Failed to parse JSON");

    let nodes_json = json.get("nodes").expect("Missing 'nodes'");
