    let content = fs::read_to_string(path).expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value().expect("Failed to parse JSON");

    let nodes_json = json.get("nodes").expect("Missing 'nodes'");
    let edges_json = json.get("edges").expect("Missing 'edges'");

    let nodes: Vec<String> = nodes_json.as_arr().expect("nodes not array")
        .iter()
        .map(|n| n.as_str().expect("node not string").to_string())
        .collect();

    let node_index: HashMap<&str, usize> = nodes.iter().enumerate()
        .map(|(i, n)| (n.as_str(), i))
        .collect();

    let n = nodes.len();
    let mut adj: Vec<Vec<(usize, f64)>> = vec![vec![]; n];

    for edge in edges_json.as_arr().expect("edges not array") {
        let from = edge.get("from").expect("missing from").as_str().expect("from not str");
        let to = edge.get("to").expect("missing to").as_str().expect("to not str");
        let weight = edge.get("weight").expect("missing weight").as_num().expect("weight not num");

        let fi = *node_index.get(from).expect("from node not found");
        let ti = *node_index.get(to).expect("to node not found");

        adj[fi].push((ti, weight));
        adj[ti].push((fi, weight));
    }

    let start_idx = *node_index.get("A").expect("Node A not found");

    let mut dist: Vec<f64> = vec![f64::INFINITY; n];
    dist[start_idx] = 0.0;

    let mut heap: BinaryHeap<Reverse<HeapEntry>> = BinaryHeap::new();
    heap.push(Reverse(HeapEntry(0.0, start_idx)));

    while let Some(Reverse(HeapEntry(d, u))) = heap.pop() {
        if d > dist[u] {
            continue;
        }
        for &(v, w) in &adj[u] {
            let nd = d + w;
            if nd < dist[v] {
                dist[v] = nd;
                heap.push(Reverse(HeapEntry(nd, v)));
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted: Vec<usize> = (0..n).collect();
    sorted.sort_by(|a, b| nodes[*a].cmp(&nodes[*b]));

    for idx in sorted {
        let name = &nodes[idx];
        let d = dist[idx];
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", name);
        } else if d == d.floor() && d.abs() < 1e15 {
            println!("A -> {}: {}", name, d as i64);
        } else {
            println!("A -> {}: {}", name, d);
        }
    }
}
