#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

typedef enum { J_NULL, J_BOOL, J_NUMBER, J_STRING, J_ARRAY, J_OBJECT } jtype;

typedef struct jvalue {
    jtype type;
    int boolval;
    double numval;
    char *numstr;
    char *str;
    size_t str_len;
    struct jvalue **items;
    size_t len, cap;
    char **keys;
    struct jvalue **vals;
    size_t olen, ocap;
} jvalue;

static jvalue *new_value(jtype t) {
    jvalue *v = (jvalue *)calloc(1, sizeof(jvalue));
    if (!v) exit(1);
    v->type = t;
    return v;
}

static void free_value(jvalue *v) {
    if (!v) return;
    if (v->type == J_ARRAY) {
        for (size_t i = 0; i < v->len; i++) free_value(v->items[i]);
        free(v->items);
    } else if (v->type == J_OBJECT) {
        for (size_t i = 0; i < v->olen; i++) {
            free(v->keys[i]);
            free_value(v->vals[i]);
        }
        free(v->keys);
        free(v->vals);
    }
    free(v->numstr);
    free(v->str);
    free(v);
}

static char *str_dup_len(const char *s, size_t len) {
    char *r = (char *)malloc(len + 1);
    if (!r) exit(1);
    memcpy(r, s, len);
    r[len] = '\0';
    return r;
}

static jvalue *deep_copy(jvalue *v) {
    if (!v) return NULL;
    jvalue *c = new_value(v->type);
    c->boolval = v->boolval;
    c->numval = v->numval;
    if (v->numstr) c->numstr = strdup(v->numstr);
    if (v->str) {
        c->str = str_dup_len(v->str, v->str_len);
        c->str_len = v->str_len;
    }
    if (v->type == J_ARRAY) {
        c->cap = v->cap;
        c->len = v->len;
        if (v->len > 0) {
            c->items = (jvalue **)malloc(v->len * sizeof(jvalue *));
            for (size_t i = 0; i < v->len; i++) c->items[i] = deep_copy(v->items[i]);
        }
    } else if (v->type == J_OBJECT) {
        c->ocap = v->ocap;
        c->olen = v->olen;
        if (v->olen > 0) {
            c->keys = (char **)malloc(v->olen * sizeof(char *));
            c->vals = (jvalue **)malloc(v->olen * sizeof(jvalue *));
            for (size_t i = 0; i < v->olen; i++) {
                c->keys[i] = strdup(v->keys[i]);
                c->vals[i] = deep_copy(v->vals[i]);
            }
        }
    }
    return c;
}

typedef struct {
    char *data;
    size_t len, cap;
} strbuf;

static void sb_init(strbuf *b) {
    b->cap = 64;
    b->data = (char *)malloc(b->cap);
    if (!b->data) exit(1);
    b->len = 0;
    b->data[0] = '\0';
}

static void sb_append(strbuf *b, char c) {
    if (b->len + 2 >= b->cap) {
        b->cap *= 2;
        b->data = (char *)realloc(b->data, b->cap);
        if (!b->data) exit(1);
    }
    b->data[b->len++] = c;
    b->data[b->len] = '\0';
}

static void sb_append_utf8(strbuf *b, uint32_t cp) {
    if (cp < 0x80) {
        sb_append(b, (char)cp);
    } else if (cp < 0x800) {
        sb_append(b, (char)(0xC0 | (cp >> 6)));
        sb_append(b, (char)(0x80 | (cp & 0x3F)));
    } else if (cp < 0x10000) {
        sb_append(b, (char)(0xE0 | (cp >> 12)));
        sb_append(b, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_append(b, (char)(0x80 | (cp & 0x3F)));
    } else {
        sb_append(b, (char)(0xF0 | (cp >> 18)));
        sb_append(b, (char)(0x80 | ((cp >> 12) & 0x3F)));
        sb_append(b, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_append(b, (char)(0x80 | (cp & 0x3F)));
    }
}

static void skip_ws(const char *s, size_t *pos, size_t len) {
    while (*pos < len) {
        char c = s[*pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') (*pos)++;
        else break;
    }
}

static int parse_hex4(const char *s, size_t *pos, size_t len) {
    if (*pos + 3 >= len) return -1;
    int val = 0;
    for (int i = 0; i < 4; i++) {
        char c = s[(*pos)++];
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else return -1;
        val = (val << 4) | d;
    }
    return val;
}

static char *parse_string(const char *s, size_t *pos, size_t len, size_t *out_len) {
    if (*pos >= len || s[*pos] != '"') { if (out_len) *out_len = 0; return NULL; }
    (*pos)++;
    strbuf b;
    sb_init(&b);
    while (*pos < len) {
        char c = s[*pos];
        if (c == '"') {
            (*pos)++;
            b.data[b.len] = '\0';
            if (out_len) *out_len = b.len;
            return b.data;
        }
        if (c == '\\') {
            (*pos)++;
            if (*pos >= len) { free(b.data); if (out_len) *out_len = 0; return NULL; }
            char e = s[*pos];
            (*pos)++;
            switch (e) {
                case '"': sb_append(&b, '"'); break;
                case '\\': sb_append(&b, '\\'); break;
                case '/': sb_append(&b, '/'); break;
                case 'b': sb_append(&b, '\b'); break;
                case 'f': sb_append(&b, '\f'); break;
                case 'n': sb_append(&b, '\n'); break;
                case 'r': sb_append(&b, '\r'); break;
                case 't': sb_append(&b, '\t'); break;
                case 'u': {
                    int cp = parse_hex4(s, pos, len);
                    if (cp < 0) { free(b.data); if (out_len) *out_len = 0; return NULL; }
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (*pos + 1 < len && s[*pos] == '\\' && s[*pos + 1] == 'u') {
                            size_t save = *pos;
                            *pos += 2;
                            int lo = parse_hex4(s, pos, len);
                            if (lo >= 0xDC00 && lo <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            } else {
                                *pos = save;
                            }
                        }
                    }
                    sb_append_utf8(&b, (uint32_t)cp);
                    break;
                }
                default:
                    sb_append(&b, e);
                    break;
            }
        } else {
            sb_append(&b, c);
            (*pos)++;
        }
    }
    free(b.data);
    if (out_len) *out_len = 0;
    return NULL;
}

static jvalue *parse_number(const char *s, size_t *pos, size_t len) {
    size_t start = *pos;
    if (*pos < len && s[*pos] == '-') (*pos)++;
    if (*pos >= len || !isdigit((unsigned char)s[*pos])) return NULL;
    while (*pos < len && isdigit((unsigned char)s[*pos])) (*pos)++;
    if (*pos < len && s[*pos] == '.') {
        (*pos)++;
        if (*pos >= len || !isdigit((unsigned char)s[*pos])) return NULL;
        while (*pos < len && isdigit((unsigned char)s[*pos])) (*pos)++;
    }
    if (*pos < len && (s[*pos] == 'e' || s[*pos] == 'E')) {
        (*pos)++;
        if (*pos < len && (s[*pos] == '+' || s[*pos] == '-')) (*pos)++;
        if (*pos >= len || !isdigit((unsigned char)s[*pos])) return NULL;
        while (*pos < len && isdigit((unsigned char)s[*pos])) (*pos)++;
    }
    size_t n = *pos - start;
    char *numstr = (char *)malloc(n + 1);
    if (!numstr) return NULL;
    memcpy(numstr, s + start, n);
    numstr[n] = '\0';
    jvalue *v = new_value(J_NUMBER);
    v->numstr = numstr;
    v->numval = strtod(numstr, NULL);
    return v;
}

static jvalue *parse_value(const char *s, size_t *pos, size_t len) {
    skip_ws(s, pos, len);
    if (*pos >= len) return NULL;
    char c = s[*pos];
    if (c == '{') {
        (*pos)++;
        jvalue *v = new_value(J_OBJECT);
        skip_ws(s, pos, len);
        if (*pos < len && s[*pos] == '}') {
            (*pos)++;
            return v;
        }
        while (1) {
            skip_ws(s, pos, len);
            if (*pos >= len || s[*pos] != '"') { free_value(v); return NULL; }
            size_t klen;
            char *key = parse_string(s, pos, len, &klen);
            if (!key) { free_value(v); return NULL; }
            skip_ws(s, pos, len);
            if (*pos >= len || s[*pos] != ':') { free(key); free_value(v); return NULL; }
            (*pos)++;
            jvalue *val = parse_value(s, pos, len);
            if (!val) { free(key); free_value(v); return NULL; }
            if (v->olen >= v->ocap) {
                v->ocap = v->ocap ? v->ocap * 2 : 8;
                v->keys = (char **)realloc(v->keys, v->ocap * sizeof(char *));
                v->vals = (jvalue **)realloc(v->vals, v->ocap * sizeof(jvalue *));
                if (!v->keys || !v->vals) exit(1);
            }
            v->keys[v->olen] = key;
            v->vals[v->olen] = val;
            v->olen++;
            skip_ws(s, pos, len);
            if (*pos < len && s[*pos] == ',') {
                (*pos)++;
                continue;
            } else if (*pos < len && s[*pos] == '}') {
                (*pos)++;
                return v;
            } else {
                free_value(v);
                return NULL;
            }
        }
    } else if (c == '[') {
        (*pos)++;
        jvalue *v = new_value(J_ARRAY);
        skip_ws(s, pos, len);
        if (*pos < len && s[*pos] == ']') {
            (*pos)++;
            return v;
        }
        while (1) {
            jvalue *item = parse_value(s, pos, len);
            if (!item) { free_value(v); return NULL; }
            if (v->len >= v->cap) {
                v->cap = v->cap ? v->cap * 2 : 8;
                v->items = (jvalue **)realloc(v->items, v->cap * sizeof(jvalue *));
                if (!v->items) exit(1);
            }
            v->items[v->len++] = item;
            skip_ws(s, pos, len);
            if (*pos < len && s[*pos] == ',') {
                (*pos)++;
                continue;
            } else if (*pos < len && s[*pos] == ']') {
                (*pos)++;
                return v;
            } else {
                free_value(v);
                return NULL;
            }
        }
    } else if (c == '"') {
        size_t slen;
        char *str = parse_string(s, pos, len, &slen);
        if (!str) return NULL;
        jvalue *v = new_value(J_STRING);
        v->str = str;
        v->str_len = slen;
        return v;
    } else if (c == 't') {
        if (*pos + 4 <= len && strncmp(s + *pos, "true", 4) == 0) {
            *pos += 4;
            jvalue *v = new_value(J_BOOL);
            v->boolval = 1;
            return v;
        }
        return NULL;
    } else if (c == 'f') {
        if (*pos + 5 <= len && strncmp(s + *pos, "false", 5) == 0) {
            *pos += 5;
            jvalue *v = new_value(J_BOOL);
            v->boolval = 0;
            return v;
        }
        return NULL;
    } else if (c == 'n') {
        if (*pos + 4 <= len && strncmp(s + *pos, "null", 4) == 0) {
            *pos += 4;
            return new_value(J_NULL);
        }
        return NULL;
    } else {
        return parse_number(s, pos, len);
    }
}

static int values_equal(jvalue *a, jvalue *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case J_NULL: return 1;
        case J_BOOL: return a->boolval == b->boolval;
        case J_NUMBER: return a->numval == b->numval;
        case J_STRING:
            if (a->str_len != b->str_len) return 0;
            if (a->str_len == 0) return 1;
            return memcmp(a->str, b->str, a->str_len) == 0;
        case J_ARRAY:
            if (a->len != b->len) return 0;
            for (size_t i = 0; i < a->len; i++)
                if (!values_equal(a->items[i], b->items[i])) return 0;
            return 1;
        case J_OBJECT:
