                        r->vals = (jvalue **)realloc(r->vals, r->ocap * sizeof(jvalue *));
                        if (!r->keys || !r->vals) exit(1);
                    }
                    r->keys[r->olen] = strdup(a->keys[i]);
                    r->vals[r->olen] = merged;
                    r->olen++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (r->olen >= r->ocap) {
                    r->ocap = r->ocap ? r->ocap * 2 : 8;
                    r->keys = (char **)realloc(r->keys, r->ocap * sizeof(char *));
                    r->vals = (jvalue **)realloc(r->vals, r->ocap * sizeof(jvalue *));
                    if (!r->keys || !r->vals) exit(1);
                }
                r->keys[r->olen] = strdup(a->keys[i]);
                r->vals[r->olen] = deep_copy(a->vals[i]);
                r->olen++;
            }
        }
        for (size_t i = 0; i < b->olen; i++) {
            int found = 0;
            for (size_t j = 0; j < a->olen; j++) {
                if (strcmp(b->keys[i], a->keys[j]) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (r->olen >= r->ocap) {
                    r->ocap = r->ocap ? r->ocap * 2 : 8;
                    r->keys = (char **)realloc(r->keys, r->ocap * sizeof(char *));
                    r->vals = (jvalue **)realloc(r->vals, r->ocap * sizeof(jvalue *));
                    if (!r->keys || !r->vals) exit(1);
                }
                r->keys[r->olen] = strdup(b->keys[i]);
                r->vals[r->olen] = deep_copy(b->vals[i]);
                r->olen++;
            }
        }
        return r;
    } else if (a->type == J_ARRAY && b->type == J_ARRAY) {
        jvalue *r = new_value(J_ARRAY);
        for (size_t i = 0; i < a->len; i++) {
            int dup = 0;
            for (size_t j = 0; j < r->len; j++) {
                if (values_equal(r->items[j], a->items[i])) { dup = 1; break; }
            }
            if (!dup) {
                if (r->len >= r->cap) {
                    r->cap = r->cap ? r->cap * 2 : 8;
                    r->items = (jvalue **)realloc(r->items, r->cap * sizeof(jvalue *));
                    if (!r->items) exit(1);
                }
                r->items[r->len++] = deep_copy(a->items[i]);
            }
        }
        for (size_t i = 0; i < b->len; i++) {
            int dup = 0;
            for (size_t j = 0; j < r->len; j++) {
                if (values_equal(r->items[j], b->items[i])) { dup = 1; break; }
            }
            if (!dup) {
                if (r->len >= r->cap) {
                    r->cap = r->cap ? r->cap * 2 : 8;
                    r->items = (jvalue **)realloc(r->items, r->cap * sizeof(jvalue *));
                    if (!r->items) exit(1);
                }
                r->items[r->len++] = deep_copy(b->items[i]);
            }
        }
        return r;
    } else {
        return deep_copy(b);
    }
}

static void sort_all_objects(jvalue *v) {
    if (!v) return;
    if (v->type == J_OBJECT) {
        for (size_t i = 0; i < v->olen; i++) {
            for (size_t j = i + 1; j < v->olen; j++) {
                if (strcmp(v->keys[i], v->keys[j]) > 0) {
                    char *tk = v->keys[i]; v->keys[i] = v->keys[j]; v->keys[j] = tk;
                    jvalue *tv = v->vals[i]; v->vals[i] = v->vals[j]; v->vals[j] = tv;
                }
            }
        }
        for (size_t i = 0; i < v->olen; i++) sort_all_objects(v->vals[i]);
    } else if (v->type == J_ARRAY) {
        for (size_t i = 0; i < v->len; i++) sort_all_objects(v->items[i]);
    }
}

static void print_indent(int depth, FILE *out) {
    for (int i = 0; i < depth * 2; i++) fputc(' ', out);
}

static void print_escaped_string(const char *s, size_t len, FILE *out) {
    fputc('"', out);
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        switch (c) {
            case '"': fputs("\\\"", out); break;
            case '\\': fputs("\\\\", out); break;
            case '\b': fputs("\\b", out); break;
            case '\f': fputs("\\f", out); break;
            case '\n': fputs("\\n", out); break;
            case '\r': fputs("\\r", out); break;
            case '\t': fputs("\\t", out); break;
            default:
                if (c < 0x20) fprintf(out, "\\u%04x", (unsigned int)c);
                else fputc((int)c, out);
                break;
        }
    }
    fputc('"', out);
}

static void print_value(jvalue *v, int depth, FILE *out) {
    if (!v) { fputs("null", out); return; }
    switch (v->type) {
        case J_NULL:
            fputs("null", out);
            break;
        case J_BOOL:
            fputs(v->boolval ? "true" : "false", out);
            break;
        case J_NUMBER:
            if (v->numstr) fputs(v->numstr, out);
            else fprintf(out, "%g", v->numval);
            break;
        case J_STRING:
            if (v->str) print_escaped_string(v->str, v->str_len, out);
            else fputs("\"\"", out);
            break;
        case J_ARRAY:
            if (v->len == 0) {
                fputs("[]", out);
            } else {
                fputc('[', out);
                for (size_t i = 0; i < v->len; i++) {
                    fputc('\n', out);
                    print_indent(depth + 1, out);
                    print_value(v->items[i], depth + 1, out);
                    if (i + 1 < v->len) fputc(',', out);
                }
                fputc('\n', out);
                print_indent(depth, out);
                fputc(']', out);
            }
            break;
        case J_OBJECT:
            if (v->olen == 0) {
                fputs("{}", out);
            } else {
                fputc('{', out);
                for (size_t i = 0; i < v->olen; i++) {
                    fputc('\n', out);
                    print_indent(depth + 1, out);
                    print_escaped_string(v->keys[i], strlen(v->keys[i]), out);
                    fputs(": ", out);
                    print_value(v->vals[i], depth + 1, out);
                    if (i + 1 < v->olen) fputc(',', out);
                }
                fputc('\n', out);
                print_indent(depth, out);
                fputc('}', out);
            }
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t n = fread(buf, 1, (size_t)sz, f);
    fclose(f);
    buf[n] = '\0';
    *out_len = n;
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);
    if (!buf_a || !buf_b) return 1;

    /* Skip UTF-8 BOM if present */
    size_t off_a = 0, off_b = 0;
    if (len_a >= 3 && (unsigned char)buf_a[0] == 0xEF && (unsigned char)buf_a[1] == 0xBB && (unsigned char)buf_a[2] == 0xBF)
        off_a = 3;
    if (len_b >= 3 && (unsigned char)buf_b[0] == 0xEF && (unsigned char)buf_b[1] == 0xBB && (unsigned char)buf_b[2] == 0xBF)
        off_b = 3;

    size_t pos = off_a;
    jvalue *a = parse_value(buf_a, &pos, len_a);
    pos = off_b;
    jvalue *b = parse_value(buf_b, &pos, len_b);
    if (!a || !b) return 1;

    jvalue *merged = merge_values(a, b);
    sort_all_objects(merged);
    print_value(merged, 0, stdout);
    fputc('\n', stdout);

    free_value(a);
    free_value(b);
    free_value(merged);
    free(buf_a);
    free(buf_b);
    return 0;
}
